import 'package:material_ui/material_ui.dart'
    show GlobalMaterialLocalizations, LocalizationsDelegate;

import 'app_localizations.dart';

/// Delegates for the app's localized widgets.
///
/// `material_ui` defines its own MaterialLocalizations type, so its matching
/// delegates must be registered instead of Flutter's standard Material
/// delegates generated by `gen-l10n`.
const appLocalizationDelegates = <LocalizationsDelegate<dynamic>>[
  AppLocalizations.delegate,
  ...GlobalMaterialLocalizations.delegates,
];
